{
  "schemaVersion": 1,
  "product": "crypto-data-live-platform",
  "stack": "Python 3.12 (uv, httpx, pydantic, TA-Lib) ingestion + Supabase Postgres + Vite/React/TS/Tailwind on Cloudflare Pages behind Cloudflare Access; GitHub Actions + cron-job.org triggers; Healthchecks.io dead-mans-switch",
  "frameworkVersion": "0.1.0",
  "budget": {
    "dailyUsd": 40,
    "totalUsd": 150
  },
  "agents": {
    "implement": "codex",
    "verify": "claude",
    "research": "claude",
    "spec": "claude"
  },
  "verification": {
    "gates": [
      {
        "name": "typecheck",
        "run": "node -e \"const f=require('fs'),c=require('child_process');let r=0;const run=(cmd)=>{try{c.execSync(cmd,{stdio:'inherit'})}catch(e){r=1}};if(f.existsSync('web/package.json'))run('npm --prefix web run typecheck');if(f.existsSync('pyproject.toml'))run('uv run mypy ingest --strict');process.exit(r)\""
      },
      {
        "name": "test",
        "run": "node -e \"const f=require('fs'),c=require('child_process');let r=0;const run=(cmd)=>{try{c.execSync(cmd,{stdio:'inherit'})}catch(e){r=1}};if(f.existsSync('web/package.json'))run('npm --prefix web test');if(f.existsSync('tests'))run('uv run pytest -q');process.exit(r)\""
      }
    ],
    "requireCi": false
  },
  "research": {
    "required": true,
    "minCitations": 3
  },
  "blastRadius": [
    "**/registry*",
    "**/migrations/**",
    "**/fetchers/**",
    ".github/workflows/**",
    "**/status*",
    "**/freshness*"
  ],
  "maxAttempts": 3
}

